var n=`0483-baba-ghanoush`;var a=`world-0483`;var t=`LB`;var o=`western-asia`;var s=4;var g=49;var r={en:`Baba Ghanoush`,ua:`Баба-гануш`};var l={en:`A traditional dish from Lebanon, centered on eggplant, tahini, lemon juice, garlic. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ліван. Основні складники: баклажан, тахіні, лимонний сік, часник. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Cut the vegetables evenly and roast at 200°C for about 38 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 38 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:38,i:[[`eggplant`,760,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`tahini`,95,`g`],[`lemon-juice`,55,`ml`],[`garlic`,3,`clove`],[`extra-virgin-olive-oil`,30,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,20,`g`],[`pomegranate`,80,`g`]]}];var m={slug:n,id:a,country:`LB`,region:o,servings:4,minutes:49,title:r,text:l,steps:d};export{t as country,m as default,a as id,g as minutes,o as region,s as servings,n as slug,d as steps,l as text,r as title};